-- Grocery tab: every product gets a store aisle, worked out from its category (or its name when
-- it has none). A virtual generated column, so it is always in step with the data and needs no
-- import changes; the index stores it and makes "browse an aisle" fast. Order of the WHEN
-- clauses matters: "Frozen pizza" is frozen, "Milk chocolate" is sweets, "Peanut butter" is pantry.
ALTER TABLE products ADD COLUMN aisle TEXT GENERATED ALWAYS AS (
  CASE
    WHEN ' ' || lower(coalesce(category, name)) || ' ' GLOB '*[ -]frozen*' OR lower(coalesce(category, name)) GLOB '*ice cream*' THEN 'frozen'
    WHEN lower(coalesce(category, name)) GLOB '*candy*' OR lower(coalesce(category, name)) GLOB '*candies*'
      OR lower(coalesce(category, name)) GLOB '*chocolate*' OR lower(coalesce(category, name)) GLOB '*cookie*'
      OR lower(coalesce(category, name)) GLOB '*biscuit*' OR lower(coalesce(category, name)) GLOB '*confection*'
      OR lower(coalesce(category, name)) GLOB '*sweets*' OR lower(coalesce(category, name)) GLOB '*chewing gum*'
      OR lower(coalesce(category, name)) GLOB '*dessert*' OR lower(coalesce(category, name)) GLOB '*cakes*'
      OR lower(coalesce(category, name)) GLOB '*pastries*' OR lower(coalesce(category, name)) GLOB '*donut*'
      OR lower(coalesce(category, name)) GLOB '*doughnut*' OR lower(coalesce(category, name)) GLOB '*sweet snack*' THEN 'sweets'
    WHEN lower(coalesce(category, name)) GLOB '*chips*' OR lower(coalesce(category, name)) GLOB '*crisps*'
      OR lower(coalesce(category, name)) GLOB '*pretzel*' OR lower(coalesce(category, name)) GLOB '*popcorn*'
      OR lower(coalesce(category, name)) GLOB '*cracker*' OR lower(coalesce(category, name)) GLOB '*snack*'
      OR lower(coalesce(category, name)) GLOB '*jerky*' OR lower(coalesce(category, name)) GLOB '*nuts*'
      OR lower(coalesce(category, name)) GLOB '*seeds*' OR lower(coalesce(category, name)) GLOB '*trail mix*'
      OR lower(coalesce(category, name)) GLOB '*bars*' THEN 'snacks'
    WHEN lower(coalesce(category, name)) GLOB '*cereal*' OR lower(coalesce(category, name)) GLOB '*granola*'
      OR lower(coalesce(category, name)) GLOB '*oatmeal*' OR lower(coalesce(category, name)) GLOB '*porridge*'
      OR lower(coalesce(category, name)) GLOB '*pancake*' OR lower(coalesce(category, name)) GLOB '*waffle*'
      OR lower(coalesce(category, name)) GLOB '*breakfast*' OR lower(coalesce(category, name)) GLOB '*rolled oats*' THEN 'breakfast'
    WHEN lower(coalesce(category, name)) GLOB '*bread*' OR lower(coalesce(category, name)) GLOB '*bagel*'
      OR lower(coalesce(category, name)) GLOB '*bakery*' OR lower(coalesce(category, name)) GLOB '*muffin*'
      OR lower(coalesce(category, name)) GLOB '*tortilla*' OR lower(coalesce(category, name)) GLOB '*buns*'
      OR lower(coalesce(category, name)) GLOB '*rolls*' OR lower(coalesce(category, name)) GLOB '*croissant*' THEN 'bakery'
    WHEN lower(coalesce(category, name)) GLOB '*beverage*' OR lower(coalesce(category, name)) GLOB '*drink*'
      OR lower(coalesce(category, name)) GLOB '*soda*' OR lower(coalesce(category, name)) GLOB '*juice*'
      OR lower(coalesce(category, name)) GLOB '*water*' OR lower(coalesce(category, name)) GLOB '*coffee*'
      OR ' ' || lower(coalesce(category, name)) || ' ' GLOB '*[ -]tea[ s,-]*' OR lower(coalesce(category, name)) GLOB '*lemonade*'
      OR lower(coalesce(category, name)) GLOB '*smoothie*' OR lower(coalesce(category, name)) GLOB '*kombucha*' THEN 'drinks'
    WHEN lower(coalesce(category, name)) GLOB '*peanut butter*' OR lower(coalesce(category, name)) GLOB '*nut butter*'
      OR lower(coalesce(category, name)) GLOB '*spread*' OR lower(coalesce(category, name)) GLOB '*sauce*'
      OR lower(coalesce(category, name)) GLOB '*condiment*' OR lower(coalesce(category, name)) GLOB '*dressing*'
      OR lower(coalesce(category, name)) GLOB '*ketchup*' OR lower(coalesce(category, name)) GLOB '*mustard*'
      OR lower(coalesce(category, name)) GLOB '*mayonnaise*' OR lower(coalesce(category, name)) GLOB '*salsa*'
      OR lower(coalesce(category, name)) GLOB '*jam*' OR lower(coalesce(category, name)) GLOB '*jelly*'
      OR lower(coalesce(category, name)) GLOB '*honey*' OR lower(coalesce(category, name)) GLOB '*syrup*'
      OR lower(coalesce(category, name)) GLOB '*pasta*' OR lower(coalesce(category, name)) GLOB '*noodle*'
      OR lower(coalesce(category, name)) GLOB '*rice*' OR lower(coalesce(category, name)) GLOB '*soup*'
      OR lower(coalesce(category, name)) GLOB '*canned*' OR lower(coalesce(category, name)) GLOB '*beans*'
      OR lower(coalesce(category, name)) GLOB '*flour*' OR lower(coalesce(category, name)) GLOB '*baking*'
      OR lower(coalesce(category, name)) GLOB '*spice*' OR lower(coalesce(category, name)) GLOB '*seasoning*'
      OR lower(coalesce(category, name)) GLOB '*oils*' OR lower(coalesce(category, name)) GLOB '*vinegar*'
      OR lower(coalesce(category, name)) GLOB '*pickle*' OR lower(coalesce(category, name)) GLOB '*sugars*'
      OR lower(coalesce(category, name)) GLOB '*grain*' OR lower(coalesce(category, name)) GLOB '*meal kit*' THEN 'pantry'
    WHEN lower(coalesce(category, name)) GLOB '*milk*' OR lower(coalesce(category, name)) GLOB '*cheese*'
      OR lower(coalesce(category, name)) GLOB '*yogurt*' OR lower(coalesce(category, name)) GLOB '*yoghurt*'
      OR lower(coalesce(category, name)) GLOB '*dairy*' OR lower(coalesce(category, name)) GLOB '*butter*'
      OR lower(coalesce(category, name)) GLOB '*cream*' OR lower(coalesce(category, name)) GLOB '*eggs*' THEN 'dairy'
    WHEN lower(coalesce(category, name)) GLOB '*meat*' OR lower(coalesce(category, name)) GLOB '*beef*'
      OR lower(coalesce(category, name)) GLOB '*chicken*' OR lower(coalesce(category, name)) GLOB '*pork*'
      OR lower(coalesce(category, name)) GLOB '*turkey*' OR lower(coalesce(category, name)) GLOB '*sausage*'
      OR lower(coalesce(category, name)) GLOB '*bacon*' OR lower(coalesce(category, name)) GLOB '*poultry*'
      OR lower(coalesce(category, name)) GLOB '*fish*' OR lower(coalesce(category, name)) GLOB '*seafood*'
      OR lower(coalesce(category, name)) GLOB '*tuna*' OR lower(coalesce(category, name)) GLOB '*salmon*'
      OR lower(coalesce(category, name)) GLOB '*deli*' OR lower(coalesce(category, name)) GLOB '*hot dog*' THEN 'meat'
    WHEN lower(coalesce(category, name)) GLOB '*fruit*' OR lower(coalesce(category, name)) GLOB '*vegetable*'
      OR lower(coalesce(category, name)) GLOB '*produce*' OR lower(coalesce(category, name)) GLOB '*salad*' THEN 'produce'
  END
) VIRTUAL;

-- Browse an aisle: products with an ingredient list (the verdict needs it) and a photo first.
CREATE INDEX products_aisle ON products (aisle, (image_url IS NULL), id) WHERE ingredients_text IS NOT NULL;
